import 'dart:async';

import 'package:audioplayers/audioplayers.dart';

/// Short procedural sound effects (assets/audio, generated by
/// tool/generate_sounds.py). All playback is fire-and-forget and gated by
/// the user's "Sound effects" setting.
class SoundService {
  SoundService({required this.isEnabled});

  final bool Function() isEnabled;

  /// A small pool so rapid keyboard taps don't cut each other off.
  final List<AudioPlayer> _tapPool = [];
  int _tapIndex = 0;
  final Map<String, AudioPlayer> _players = {};
  bool _ready = false;

  Future<void> initialize() async {
    try {
      await AudioPlayer.global.setAudioContext(
        AudioContextConfig(
          // Respect silent mode and never duck other apps' music: these are
          // UI blips, not media.
          focus: AudioContextConfigFocus.mixWithOthers,
          respectSilence: true,
        ).build(),
      );
      for (var i = 0; i < 3; i++) {
        _tapPool.add(await _load('tap.wav'));
      }
      for (final name in [
        'hint.wav',
        'conflict.wav',
        'success.wav',
        'achievement.wav',
        'word.wav',
      ]) {
        _players[name] = await _load(name);
      }
      _ready = true;
    } catch (_) {
      // Audio is never worth crashing over (emulators without audio,
      // restricted web contexts...): stay silent instead.
      _ready = false;
    }
  }

  Future<AudioPlayer> _load(String asset) async {
    final p = AudioPlayer();
    await p.setPlayerMode(PlayerMode.lowLatency);
    await p.setSource(AssetSource('audio/$asset'));
    await p.setReleaseMode(ReleaseMode.stop);
    return p;
  }

  void _play(AudioPlayer? player) {
    if (!_ready || player == null || !isEnabled()) return;
    // Fire and forget; errors are irrelevant for a UI blip.
    unawaited(player.stop().then((_) => player.resume()).catchError((_) {}));
  }

  void tap() {
    if (_tapPool.isEmpty) return;
    _tapIndex = (_tapIndex + 1) % _tapPool.length;
    _play(_tapPool[_tapIndex]);
  }

  void hint() => _play(_players['hint.wav']);

  void conflict() => _play(_players['conflict.wav']);

  /// A single soft bell when a typed guess finishes a whole word.
  void wordComplete() => _play(_players['word.wav']);

  void success() => _play(_players['success.wav']);

  void achievement() => _play(_players['achievement.wav']);

  void dispose() {
    for (final p in [..._tapPool, ..._players.values]) {
      p.dispose();
    }
  }
}
